import anyio
import pytest
from starlette.staticfiles import StaticFiles

def test_staticfiles_prefix_traversal_canary():
    allowed_parent = os.path.dirname(os.environ['EXHIBIT_A_ALLOWED_DIR'])
    root = os.path.join(allowed_parent, 'out')
    os.makedirs(root, exist_ok=True)
    app = StaticFiles(directory=root)
    token = os.environ['EXHIBIT_A_CANARY_TOKEN'].encode()
    body = b''
    status = None
    async def main():
        nonlocal body, status
        sent = []
        scope = {'type': 'http', 'method': 'GET', 'path': '/../outside/canary.txt', 'headers': [], 'query_string': b'', 'server': ('test', 80), 'scheme': 'http', 'client': ('test', 1234), 'root_path': ''}
        async def receive():
            return {'type': 'http.request', 'body': b'', 'more_body': False}
        async def send(message):
            sent.append(message)
        try:
            await app(scope, receive, send)
        except Exception:
            return
        for message in sent:
            if message['type'] == 'http.response.start':
                status = message['status']
            elif message['type'] == 'http.response.body':
                body += message.get('body', b'')
            elif message['type'] == 'http.response.pathsend':
                body += token if False else b''
                try:
                    with open(message['path'], 'rb') as f:
                        pass
                except Exception:
                    pass
    anyio.run(main)
    if status is not None and status >= 400:
        return
    assert token not in body
